Console.Write("Willst du weiterspielen? ");
string antwort = Console.ReadLine().Trim().ToLower();

if (antwort == "ja")
{
    Console.WriteLine("Auf geht's!");
}
else
{
    Console.WriteLine("Bis zum nächsten Mal.");
}
// Eingabe:  JA
// Ausgabe: Auf geht's!

string mail = "anna.huber@schule.at";
int at = mail.IndexOf("@");

Console.WriteLine(mail.Substring(0, at));    // anna.huber
Console.WriteLine(mail.Substring(at + 1));   // schule.at
Console.WriteLine(mail.Replace(".", " "));   // anna huber@schule at

Console.Write("Gib Zahlen ein (mit Leerzeichen getrennt): ");
string[] teile = Console.ReadLine().Split(' ');
int summe = 0;

foreach (string teil in teile)
{
    summe += int.Parse(teil);
}

Console.WriteLine($"{teile.Length} Zahlen, Summe {summe}");
Console.WriteLine(string.Join(" + ", teile));
// Eingabe:  4 8 15
// Ausgabe:
// 3 Zahlen, Summe 27
// 4 + 8 + 15

